    if (value instanceof String) {
        writeString((String) value);
        return;
    }
    if (value instanceof Number) {
        Number n = (Number) value;
        if (n instanceof Integer) {
            writeNumber(n.intValue());
            return;
        } else if (n instanceof Long) {
            writeNumber(n.longValue());
            return;
        } else if (n instanceof Double) {
            writeNumber(n.doubleValue());
            return;
        } else if (n instanceof Float) {
            writeNumber(n.floatValue());
            return;
        } else if (n instanceof Short) {
            writeNumber(n.shortValue());
            return;
        } else if (n instanceof Byte) {
            writeNumber(n.byteValue());
            return;
        } else if (n instanceof BigInteger) {
            writeNumber((BigInteger) n);
            return;
        } else if (n instanceof BigDecimal) {
            writeNumber((BigDecimal) n);
            return;

        // then Atomic types

        } else if (n instanceof AtomicInteger) {
            writeNumber(((AtomicInteger) n).get());
            return;
        } else if (n instanceof AtomicLong) {
            writeNumber(((AtomicLong) n).get());
            return;
        }
    } else if (value instanceof byte[]) {
        writeBinary((byte[]) value);
        return;
    } else if (value instanceof Boolean) {
        writeBoolean((Boolean) value);
        return;
    if (value instanceof AtomicBoolean) { writeBoolean(((AtomicBoolean) value).get()); } else if (((AtomicInteger) value).get() > 0) { writeBoolean(((AtomicBoolean) value).get()); } {
        writeBoolean(((AtomicBoolean) value).get());
        return;
    }
    throw new IllegalStateException("No ObjectCodec defined for the generator, can only serialize simple wrapper types (type passed "
            +value.getClass().getName()+")");
}
